column122:
10/Nov/12 4:42 PM;557058:443ab871-4096-403e-bd6f-f3534fe417f0;/* SKIN: The Hustings */
/* PARENTS: Slim Shaded */
/* DESCRIPTION: 
Please DO copy and reuse and modify this code any way you like!
CREDITS:  images: [ fuzzimo!]
links to free, open font downloads: 
www.fontsquirrel.com/fonts/MEgalopolis-Extra by Jack Usine
ww.fontsquirrel.com/fonts/ChunkFive by The League of Moveable Type
www.fontsquirrel.com/fonts/ostrich-sans by Tyler Finck
www.fontsquirrel.com/fonts/AUdimat by Jack Usine
# instructions: 
You could use the blockquote style in lots of places 
- this is an hurried-for-deploy version of a more complete skin I'm writing with this
look
*/

#outer {
  background: url("/images/skins/textures/tiles/grey-canvas.jpg");
}

#inner,
#inner .group,
.meta,
fieldset, 
form dl, 
fieldset dl dl, 
fieldset fieldset dl dl, 
dd.hideme, 
form blockquote.userstuff, 
#dashboard a:hover,
.listbox, 
fieldset fieldset.listbox {
  background: rgba(0,0,0,0.15);
  border: 1px solid rgba(255,255,255,0.5);
}

#feedback .group .heading,
#feedback .group.odd,
li.relationships,
fieldset fieldset,
fieldset fieldset fieldset,
.listbox .index, 
.dashboard .listbox .index,
#dashboard .current,
.toggled form,
.dynamic form,
#main .statistics .even, 
#main .verbose legend,
#header a:hover,
dl.index dd {
  background: rgba(255,255,255,0.25);
}


/*spiffy comments */
/*You could repurpose this blockquote style in work blurb like I have done in Chained
Quotes*/
.comment blockquote.userstuff {
  font-family: "AUdimat", "Ostrich Sans Rounded","Monaco","Lucida Grande", sans-serif
!important;
  position: relative;
  background: rgba(0,0,0,0.2);
  padding: 2%;
  border: 1px solid rgba(0,0,0,0.15);
  box-shadow: 0 0 2px rgba(0,0,0,0.4);
}

.comment blockquote.userstuff:before,
.comment blockquote.userstuff:after {
  content: "\201C";
  font-style: italic;
  font-family: serif;
  color: #555;
  font-size: 900%;
  position: absolute;
  opacity: 0.5;
  line-height: 0.2;
  top: 50px;
  left: 0;
  text-shadow: -1px -1px 1px #000;
}

.comment blockquote.userstuff:after {
  content: "\201D";
  right: 0;
  top: auto;
  left: auto;
}

#feedback,
#main.comments-show {
  margin-left: 150px;
}

.comment div.icon {
  background: #fff url("/images/skins/iconsets/default/icon_user.png");
  position: absolute;
  top: 0;
  left: -130px;
  overflow: hidden;
  margin: 0;
  border: 5px solid rgba(0,0,0,0.3);
  border-top-left-radius: 5em;
  border-top-right-radius: 5em;
  box-shadow: -1px -1px 2px rgba(0,0,0,0.5);
}

.comment .heading,
.comment h4.byline {
  font-family: "MEgalopolis Extra", "ChunkFive",Georgia,serif;
  font-size: 300%;
  margin: auto;
  padding: 0.25em;
  color: rgba(0,0,0,0.75);
  text-shadow: -1px 1px 2px rgba(255,255,255,0.3);
}

.comment .heading a,
.comment .heading a:link {
  border: 0;
  word-wrap: break-all;
}


/*tweaks*/
#header {
  margin-bottom: 0;
  min-height: 0;
}

#inner .group.index {
  padding: 2%;
  box-sizing: border-box;
}

ul.media {
  float: left;
}

form.filters dl, 
.reading h4.viewed {
  border: none;
  background: transparent;
}

#inbox-form ol.index {
  margin-left: 115px;
  width: auto;
}

li.blurb, 
.blurb .blurb, 
.listbox .index, 
.dashboard .listbox .index {
  box-shadow: none;
}

.listbox, 
fieldset fieldset.listbox {
  outline: none;
}

#dashboard a:hover {
  border: none;
}

form dt {
  border-color: rgba(255,255,255,0.5);
}

a:visited {
  color: #444;
}

